    /// `cf.if %c { … } else { … }`: two regions.
    ///
    /// Builds each region in a closure, with the insertion point at its end, and returns to
    /// the insertion point after the op.
    pub fn cf_if(&mut self, results: &[Ty], cond: impl Into<Operand>, then_: impl FnOnce(&mut Self) -> Result<(), BuildError>, else_: impl FnOnce(&mut Self) -> Result<(), BuildError>) -> Result<Results, BuildError> {
        let op = self.cf_if_begin(results, cond)?;
        let r = self.region(op, 0)?;
        self.in_region(r, then_)?;
        let r = self.region(op, 1)?;
        self.in_region(r, else_)?;
        Ok(self.all_results(op))
    }

