    /// `cf.blocks [progress] { ^entry: … ^b(%x: i32): … }`: labeled blocks, entered at the first
    /// (which has no parameters), with jumps between them. Each block ends with a terminator:
    /// `cf.yield` leaves with the op's results; `cf.br`, `cf.cond_br`, and `cf.switch` jump. With
    /// `progress`, control may be assumed to leave the op (as for `cf.loop progress`).
    ///
    /// Builds each region in a closure, with the insertion point at its end, and returns to
    /// the insertion point after the op.
    pub fn cf_blocks(&mut self, results: &[Ty], progress: bool, blocks: impl FnOnce(&mut Self, OpId) -> Result<(), BuildError>) -> Result<Results, BuildError> {
        let op = self.cf_blocks_begin(results, progress)?;
        self.in_blocks(op, blocks)?;
        Ok(self.all_results(op))
    }

