    pub fn cf_cond_br(&mut self, cond: impl Into<Operand>, t: Target<'_>, f: Target<'_>) -> Result<OpId, BuildError> {
        self.begin_op();
        self.operand(cond.into());
        let t_id = self.succ(t)?;
        let f_id = self.succ(f)?;
        let kind = OpKind::CondBr { t: t_id, f: f_id };
        self.simple(kind, Res::None)
    }

    /// `cf.switch %v, default ^d(…), [k: ^b(…), …]`: jump to the case whose key is `%v` (keys are
    /// taken modulo `2^N`), or to the default. Branching on `poison` is UB.
    pub fn cf_switch(&mut self, x: impl Into<Operand>, dflt: Target<'_>, cases: &[SwitchCase<'_>]) -> Result<OpId, BuildError> {
        self.begin_op();
        self.operand(x.into());
        let dflt_id = self.succ(dflt)?;
        let cases_id = self.cases(cases)?;
        let kind = OpKind::Switch { dflt: dflt_id, cases: cases_id };
        self.simple(kind, Res::None)
    }

